def skill():
    x = Symbol('x')
    P = (x + 1)*(x - 1)*(x - 3)
    return sum(abs(diff(P, x).subs(x, r)) for r in (-1, 1, 3))

def standard():
    x, a, b, c = symbols('x a b c')
    P = (x + 1)*(x - 1)*(x - 3)
    roots_ = [-1, 1, 3]
    coef = {-1: a, 1: b, 3: c}
    eqs = []
    for r in roots_:
        slopes = []
        for side in (-1, 1):
            xt = r + side*Rational(1, 100)
            sP = sign(P.subs(x, xt))
            H = sP*P
            for rr in roots_:
                H = H - coef[rr]*sign(xt - rr)*(x - rr)
            slopes.append(diff(H, x).subs(x, r))
        eqs.append(slopes[0] - slopes[1])
    s = solve(eqs, [a, b, c])
    return s[a] + s[b] + s[c]

def unique():
    return [standard()]
